package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE, 44 bytes
	TierEntry struct { // group @0 len=11
		TierLimit decimal.Decimal // PIC 9(6)V99 @0 len=8
		TierRate  decimal.Decimal // PIC 9V99 @8 len=3
	}
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.New(0, 0)
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

// helpers for tier table (1-based)
var tierLimit [5]decimal.Decimal
var tierRate [5]decimal.Decimal

var salesFile *os.File
var reader *bufio.Reader
var atEOF bool

var srRec SalesRec

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func parseDisplayInt(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, -scale)
	}
	// s should be digits; if contains non-digit, strip? Assume digits.
	// Remove possible sign? not needed.
	// Parse as integer
	d, err := decimal.NewFromString(s)
	if err != nil {
		// if spaces inside, remove spaces
		s2 := strings.ReplaceAll(s, " ", "")
		if s2 == "" {
			return decimal.New(0, -scale)
		}
		d, _ = decimal.NewFromString(s2)
	}
	// shift
	return d.Shift(-scale)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// generic edited formatter
func formatEdited(value decimal.Decimal, picture string) string {
	// picture contains Z , . 9
	// Determine scale = number of '9' after '.'
	dotPos := strings.Index(picture, ".")
	var leftPic, rightPic string
	var scale int
	if dotPos >= 0 {
		leftPic = picture[:dotPos]
		rightPic = picture[dotPos+1:]
		scale = len(rightPic) // assume all 9
	} else {
		leftPic = picture
		rightPic = ""
		scale = 0
	}
	// Ensure value has correct scale for display: we assume value already at scale
	// Get absolute representation with scale digits
	// Use Shift to get integer representation
	// We need integer part and fractional part
	// For truncation/dropping high order, handle integer digits count
	intDigitCount := 0
	for _, c := range leftPic {
		if c == 'Z' || c == '9' {
			intDigitCount++
		}
	}
	// Get integer and fractional strings
	// Round/truncate not needed; value scale should be == scale
	// Use StringFixed to get exactly scale decimals
	fixed := value.StringFixed(int32(scale))
	// fixed is like "1000.00" or "0.00" possibly with minus
	isNeg := false
	if strings.HasPrefix(fixed, "-") {
		isNeg = true
		fixed = fixed[1:]
	}
	var intPartStr, fracPartStr string
	if scale > 0 {
		parts := strings.SplitN(fixed, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", scale)
		}
	} else {
		intPartStr = fixed
		fracPartStr = ""
	}
	// Handle high-order truncation for integer part
	if len(intPartStr) > intDigitCount {
		intPartStr = intPartStr[len(intPartStr)-intDigitCount:]
	} else if len(intPartStr) < intDigitCount {
		intPartStr = strings.Repeat("0", intDigitCount-len(intPartStr)) + intPartStr
	}
	// Build left chars
	leftChars := make([]rune, len(leftPic))
	digitIdx := len(intPartStr) - 1 // index into intPartStr
	for i := len(leftPic) - 1; i >= 0; i-- {
		c := leftPic[i]
		if c == ',' {
			leftChars[i] = ','
		} else if c == 'Z' || c == '9' {
			if digitIdx >= 0 {
				leftChars[i] = rune(intPartStr[digitIdx])
				digitIdx--
			} else {
				leftChars[i] = '0'
			}
		} else {
			leftChars[i] = rune(c)
		}
	}
	// Zero suppression for Z
	suppress := true
	for i := 0; i < len(leftPic); i++ {
		pc := rune(leftPic[i])
		if pc == ',' {
			if suppress {
				leftChars[i] = ' '
			} else {
				leftChars[i] = ','
			}
		} else if pc == 'Z' {
			if suppress && leftChars[i] == '0' {
				// look ahead for any non-zero digit in remaining Z/9 positions
				hasNonZeroAhead := false
				for k := i + 1; k < len(leftPic); k++ {
					pk := rune(leftPic[k])
					if pk == 'Z' || pk == '9' {
						if leftChars[k] != '0' {
							hasNonZeroAhead = true
							break
						}
					}
				}
				if hasNonZeroAhead {
					leftChars[i] = ' '
				} else {
					// all zeros ahead, this leading zero is suppressed
					leftChars[i] = ' '
				}
				// remain suppress true if we turned to space
				if leftChars[i] == ' ' {
					suppress = true
				} else {
					suppress = false
				}
			} else {
				// non-zero digit ends suppression; zero after suppression stays zero
				if leftChars[i] != ' ' {
					suppress = false
				}
			}
		} else if pc == '9' {
			// mandatory
			suppress = false
		}
	}
	// Assemble
	var out string
	out = string(leftChars)
	if scale > 0 {
		// ensure frac length
		if len(fracPartStr) < scale {
			fracPartStr = fracPartStr + strings.Repeat("0", scale-len(fracPartStr))
		} else if len(fracPartStr) > scale {
			fracPartStr = fracPartStr[:scale]
		}
		out = out + "." + fracPartStr
	}
	if isNeg {
		// not needed for this program, but handle: put minus before first digit? ignore
		out = "-" + out
	}
	// Ensure width equals picture length
	if len(out) < len(picture) {
		// Should not happen because leftChars already width, but pad left with spaces
		out = strings.Repeat(" ", len(picture)-len(out)) + out
	} else if len(out) > len(picture) {
		out = out[len(out)-len(picture):]
	}
	return out
}

func formatPICZZZZZ9_99(v decimal.Decimal) string {
	return formatEdited(v, "ZZZ,ZZ9.99")
}
func formatPICZZZZZZZZ9_99(v decimal.Decimal) string {
	return formatEdited(v, "ZZZ,ZZZ,ZZ9.99")
}
func formatPIC9_99(v decimal.Decimal) string {
	return formatEdited(v, "9.99")
}
func formatPIC9(v int64) string {
	return fmt.Sprintf("%01d", v)
}
func formatPIC9_3(v int64) string {
	return fmt.Sprintf("%03d", v)
}

func initPara() {
	tierLimit[1] = decimal.NewFromFloat(1000.00)
	tierLimit[2] = decimal.NewFromFloat(5000.00)
	tierLimit[3] = decimal.NewFromFloat(20000.00)
	tierLimit[4] = decimal.NewFromFloat(999999.99)
	// Use exact decimals
	tierLimit[1] = decimal.New(100000, -2)
	tierLimit[2] = decimal.New(500000, -2)
	tierLimit[3] = decimal.New(2000000, -2)
	tierLimit[4] = decimal.New(99999999, -2)

	tierRate[1] = decimal.New(250, -2) // 2.50
	tierRate[2] = decimal.New(400, -2) // 4.00
	tierRate[3] = decimal.New(550, -2) // 5.50
	tierRate[4] = decimal.New(725, -2) // 7.25
}

func readPara() {
	line, err := reader.ReadString('\n')
	if err != nil {
		// EOF handling: if we got some data without newline, process it, else mark done
		if len(line) == 0 {
			WsEofFlag = "Y"
			atEOF = true
			return
		}
		// have partial line
		line = strings.TrimRight(line, "\r\n")
		// process line then next read will be EOF
		// pad and parse
		rec := padRight(line, 12)
		srRec.SrId = rec[0:4]
		srRec.SrSales = parseDisplayInt(rec[4:12], 2)
		// next call will be EOF, but for now not done. We need to return and on next call detect EOF.
		// To emulate COBOL LINE SEQUENTIAL, after this line, next read will be EOF.
		// So we set a flag to handle next read.
		// Instead, set reader to return EOF next time.
		// We already consumed line; set WsEofFlag still N, but next read will be Y.
		// Need to handle by storing that we need to return this record now.
		// Our err != nil (EOF) but we have line content; we should not set INPUT-DONE yet.
		// So keep WsEofFlag N, but arrange next call to return EOF.
		// We can keep atEOF pending: set a variable pendingEOF
		pendingEOF = true
		return
	}
	line = strings.TrimRight(line, "\r\n")
	rec := padRight(line, 12)
	srRec.SrId = rec[0:4]
	srRec.SrSales = parseDisplayInt(rec[4:12], 2)
	if pendingEOF {
		// not needed
	}
}

var pendingEOF bool

func processPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && WsTier == 0; WsIdx++ {
		if srRec.SrSales.Cmp(tierLimit[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE /100
	// Multiply before dividing, Round to 2
	prod := srRec.SrSales.Mul(tierRate[WsTier])
	// divide by 100 -> Shift(-2)
	div := prod.Shift(-2)
	rounded := div.Round(2)
	// Store into PIC 9(6)V99 : keep low-order digits, truncate to 2 (already)
	// High-order truncation if exceeds 6 integer digits (not expected)
	WsComm = truncateDecimal(rounded, 2)
	// ADD to TOTAL (truncate)
	WsTotal = truncateDecimal(WsTotal.Add(WsComm), 2)
	WsCount++

	WsSalesEd = formatPICZZZZZ9_99(srRec.SrSales)
	WsRateEd = formatPIC9_99(tierRate[WsTier])
	WsCommEd = formatPICZZZZZ9_99(WsComm)

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	fmt.Printf("%s T%s %s %s%% %s\n", srRec.SrId, formatPIC9(WsTier), WsSalesEd, WsRateEd, WsCommEd)

	// READ next
	if pendingEOF {
		WsEofFlag = "Y"
		atEOF = true
		pendingEOF = false
		return
	}
	readPara()
}

func summaryPara() {
	WsTotalEd = formatPICZZZZZZZZ9_99(WsTotal)
	// DISPLAY "REPS: " WS-COUNT " TOTAL: " WS-TOTAL-ED
	// WS-COUNT is PIC 9(3) zero padded
	fmt.Printf("REPS: %s TOTAL: %s\n", formatPIC9_3(WsCount), WsTotalEd)
}

func main() {
	initPara()
	var err error
	salesFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		salesFile = nil
		reader = bufio.NewReader(strings.NewReader(""))
		atEOF = true
		WsEofFlag = "Y"
		summaryPara()
		return
	}
	defer salesFile.Close()
	reader = bufio.NewReader(salesFile)

	readPara()
	if WsEofFlag == "Y" {
		// no records
	} else {
		for WsEofFlag != "Y" {
			processPara()
		}
	}
	summaryPara()
	_ = atEOF
}
